ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "emailVerificationTokenHash" TEXT, ADD COLUMN IF NOT EXISTS "emailVerificationExpiresAt" TIMESTAMP(3);
ALTER TABLE "Listing" ADD COLUMN IF NOT EXISTS "city" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "deliveryMethod" TEXT NOT NULL DEFAULT 'ANY', ADD COLUMN IF NOT EXISTS "specifications" JSONB NOT NULL DEFAULT '{}';
ALTER TABLE "Order" ADD COLUMN IF NOT EXISTS "reservationExpiresAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "settlementMethod" TEXT NOT NULL DEFAULT 'COD', ADD COLUMN IF NOT EXISTS "codCollectedAt" TIMESTAMP(3);
UPDATE "Order" SET "reservationExpiresAt" = CURRENT_TIMESTAMP + INTERVAL '30 minutes' WHERE "status" = 'PENDING_DEPOSIT';
ALTER TABLE "Review" ADD COLUMN IF NOT EXISTS "sentiment" TEXT NOT NULL DEFAULT 'NEUTRAL', ADD COLUMN IF NOT EXISTS "sentimentSource" TEXT NOT NULL DEFAULT 'LOCAL';
CREATE TABLE IF NOT EXISTS "PriceHistory" ("id" SERIAL PRIMARY KEY, "listingId" INTEGER NOT NULL REFERENCES "Listing"("id") ON DELETE CASCADE, "price" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "PriceHistory_listingId_createdAt_idx" ON "PriceHistory"("listingId", "createdAt");
INSERT INTO "PriceHistory" ("listingId", "price") SELECT "id", "price" FROM "Listing" l WHERE NOT EXISTS (SELECT 1 FROM "PriceHistory" h WHERE h."listingId" = l."id");
CREATE TABLE IF NOT EXISTS "SavedSearch" ("id" SERIAL PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "filters" JSONB NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "SavedSearch_userId_idx" ON "SavedSearch"("userId");
CREATE TABLE IF NOT EXISTS "SavedSearchMatch" ("searchId" INTEGER NOT NULL REFERENCES "SavedSearch"("id") ON DELETE CASCADE, "listingId" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("searchId", "listingId"));
